import heapq


class Helpdesk:
    PRIORITIES = ("normal", "high", "critical")

    def __init__(self) -> None:
        self._customers = {}
        self._tickets = {}
        self._queue = []
        self._next_id = 1

    def add_customer(self, name: str, vip: bool = False) -> None:
        if name in self._customers:
            raise ValueError("Customer already exists")
        self._customers[name] = vip

    def open_ticket(self, customer: str, title: str, priority: str = "normal") -> int:
        if not title:
            raise ValueError("Ticket title cannot be empty")
        if customer not in self._customers:
            raise KeyError(customer)
        if priority not in self.PRIORITIES:
            raise ValueError("Invalid priority")

        ticket_id = self._next_id
        self._next_id += 1
        self._tickets[ticket_id] = {
            "customer": customer,
            "title": title,
            "priority": priority,
            "state": "queued",
            "generation": 0,
        }
        self._enqueue(ticket_id)
        return ticket_id

    def _enqueue(self, ticket_id: int) -> None:
        ticket = self._tickets[ticket_id]
        heapq.heappush(
            self._queue,
            (
                not self._customers[ticket["customer"]],
                -self.PRIORITIES.index(ticket["priority"]),
                ticket_id,
                ticket["generation"],
            ),
        )

    def next_ticket(self) -> int | None:
        while self._queue:
            _, _, ticket_id, generation = heapq.heappop(self._queue)
            ticket = self._tickets[ticket_id]
            if ticket["state"] == "queued" and ticket["generation"] == generation:
                ticket["state"] = "in_progress"
                return ticket_id
        return None

    def close(self, ticket_id: int) -> None:
        ticket = self._tickets[ticket_id]
        ticket["state"] = "closed"
        ticket["generation"] += 1

    def reopen(self, ticket_id: int) -> None:
        ticket = self._tickets[ticket_id]
        if ticket["state"] != "queued":
            ticket["state"] = "queued"
            ticket["generation"] += 1
            self._enqueue(ticket_id)
